import { createServer, type Server } from "node:http";
import { expect, test, type Frame, type Page } from "@playwright/test";
import { unzipSync } from "fflate";
import { E2E_SAR_HOME } from "../playwright.config";

// Template structure, for real: a template generated by the actual
// SaveAllResources CLI from a small TEST FIXTURE site served here, edited
// through the template page (reorder, duplicate, insert, remove, split,
// exclude, token detach, undo), each change checked in the live preview,
// then Web's checks and the exported deliverable. No model is involved.

test.describe.configure({ mode: "serial" });
test.skip(!E2E_SAR_HOME, "SaveAllResources is not installed next to Web (set SAR_HOME)");

const html = (title: string, body: string) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>${title} · Structure Bakery</title><link rel="stylesheet" href="/css/site.css"></head>
<body><header class="site-header"><nav><a href="/">Home</a> <a href="/menu/">Menu</a></nav></header>
<main>${body}</main><footer class="site-footer"><p>Structure Bakery</p></footer><script src="/js/app.js"></script></body></html>`;
const SITE: Record<string, [string, string]> = {
  "/": ["text/html", html("Home", `<section class="hero"><h1>Fresh bread daily</h1><p>Sourdough and rye, baked every morning.</p><a class="button" href="/menu/">See the menu</a><div class="promo">Limited offer this week</div></section><section class="features" id="features"><h2>Why choose us</h2><div class="grid"><article class="card"><h3>Sourdough</h3><p>Slow risen for two days.</p></article><article class="card"><h3>Rye</h3><p>Dark, dense and nutty.</p></article><article class="card"><h3>Pastries</h3><p>Butter-rich and flaky.</p></article></div></section><section class="contact"><h2>Order ahead</h2><form action="https://orders.example.invalid/submit" method="post"><label for="email">Email</label><input id="email" name="email"><button>Send</button></form></section>`)],
  "/menu/": ["text/html", html("Menu", `<section class="hero"><h1>Our menu</h1><p>Everything is baked on site.</p></section><section class="testimonials"><h2>What people say</h2><blockquote>Best bread in town.</blockquote></section>`)],
  "/css/site.css": ["text/css", `:root { --brand: #b45309; }\nbody { font-family: Georgia, serif; color: #1f2937; background: #fffbeb; }\nh1 { color: #b45309; }\n.button { background: #b45309; color: #ffffff; padding: 8px 12px; }\n.card { border: 1px solid #b45309; padding: 8px; }\n.promo { background: #fde68a; }\n`],
  "/js/app.js": ["text/javascript", `document.getElementById("features")?.setAttribute("data-ready", "1");\n`],
};

let server: Server;
let siteUrl = "";
let templatePage = "";
test.beforeAll(async () => {
  server = createServer((req, res) => {
    const hit = SITE[(req.url ?? "/").split("?")[0]];
    if (!hit) return res.writeHead(404).end("not found");
    res.writeHead(200, { "Content-Type": hit[0] }).end(hit[1]);
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  const a = server.address();
  siteUrl = `http://127.0.0.1:${typeof a === "object" && a ? a.port : 0}/`;
});
test.afterAll(() => new Promise<void>((r) => server.close(() => r())));

const previewFrame = async (page: Page): Promise<Frame> => {
  await expect(page.locator('iframe[title="Template preview"]')).toBeVisible();
  let frame: Frame | undefined;
  await expect.poll(() => (frame = page.frames().filter((f) => f.url().startsWith("http://127.0.0.1:") && !f.isDetached()).at(-1))?.url() ?? "", { timeout: 15_000 }).toMatch(/^http:\/\/127\.0\.0\.1:/);
  await frame!.waitForLoadState();
  return frame!;
};
const buildOf = async (page: Page) => Number(await page.getByTestId("preview-state").getAttribute("data-build"));
async function rebuilt(page: Page, before: number) {
  await expect.poll(() => buildOf(page), { timeout: 30_000 }).toBeGreaterThan(before);
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready");
}
const sectionsIn = async (page: Page) => (await previewFrame(page)).$$eval("[data-sar-section]", (els) => els.map((e) => e.getAttribute("data-sar-section")));
const item = (page: Page, id: string) => page.locator(`[data-testid="section-item"][data-section-id="${id}"]`);
/** Runs a structure change and waits for the preview to rebuild with it. */
async function change(page: Page, act: () => Promise<void>, expectMessage: RegExp = /./) {
  const before = await buildOf(page);
  await act();
  await expect(page.getByTestId("structure-message")).toHaveText(expectMessage);
  await rebuilt(page, before);
}

test("a generated template's pages and sections each have a status", async ({ page }) => {
  test.setTimeout(420_000);
  await page.goto("/projects/new");
  await page.getByLabel("Client or business name").fill("Structure Client");
  await page.getByLabel("Project name").fill("Structure Client project");
  await page.getByRole("button", { name: "Create project and start brief" }).click();
  await expect(page).toHaveURL(/\/brief$/);
  await page.goto(page.url().replace(/\/brief$/, ""));
  await page.waitForLoadState("networkidle");
  await page.getByLabel(/^Website URL/).fill(siteUrl);
  await page.getByLabel(/Client-owned/).check();
  await page.getByLabel(/^Authorised by/).fill("Test owner, written permission 2026-10-02");
  await page.getByText("Capture settings").click();
  await page.getByLabel("Max pages").fill("2");
  await page.getByRole("button", { name: "Generate Website Template" }).click();
  await expect(page.getByTestId("template-pipeline")).toHaveAttribute("data-status", /waiting|completed/, { timeout: 300_000 });
  await page.getByRole("link", { name: "Preview and edit template" }).click();
  await expect(page).toHaveURL(/\/templates\/tpl_/);
  templatePage = page.url();

  // Both captured pages are templatised; none is inaccessible or needs manual work.
  await expect(page.getByTestId("coverage-pages")).toContainText(/Pages: (\d) processed · (\d) with limitations · 0 manual work · 0 inaccessible/);
  await expect(page.getByTestId("coverage-sections")).toContainText(/\d+ processed/);
  // The form has interactions the template disconnects: processed with limitations, with the reason.
  await expect(item(page, "home/s04-form").locator('[data-status="processed_with_limitations"]')).toBeVisible();
  await expect(item(page, "home/s04-form")).toContainText("Interactions: form (submission disabled until configured)");
  await expect(item(page, "home/s02-hero").locator('[data-status="processed"]')).toBeVisible();
  // Regions: the main element's sections can be rearranged among themselves.
  await expect(page.locator('[data-testid="region"]', { hasText: "inside main" }).getByTestId("section-item")).toHaveCount(3);
  await expect(page.getByTestId("source-edits")).toContainText("hard-coded colour");
});

test("reorder, duplicate, insert, remove, split and exclude sections, each visible in the live preview", async ({ page }) => {
  test.setTimeout(240_000);
  const consoleErrors: string[] = [];
  page.on("console", (m) => m.type() === "error" && !/favicon|Content Security Policy|blocked/i.test(m.text()) && consoleErrors.push(m.text()));
  await page.goto(templatePage);
  await page.getByRole("button", { name: "Start preview" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 60_000 });
  expect(await sectionsIn(page)).toEqual(["home/s01-navigation", "home/s02-hero", "home/s03-cards", "home/s04-form", "home/s05-footer"]);

  // Reorder within the region.
  await change(page, () => item(page, "home/s04-form").getByRole("button", { name: "Move home/s04-form up" }).click(), /Moved home\/s04-form up/);
  expect(await sectionsIn(page)).toEqual(["home/s01-navigation", "home/s02-hero", "home/s04-form", "home/s03-cards", "home/s05-footer"]);

  // Duplicate: a script refers to the cards section's id, so it asks first; the copy gets its own ids.
  await item(page, "home/s03-cards").getByRole("button", { name: "Duplicate home/s03-cards" }).click();
  await expect(page.getByRole("alert").filter({ hasText: "scripts refer to #features" })).toBeVisible();
  await change(page, () => page.getByRole("button", { name: "Copy anyway" }).click(), /Duplicated home\/s03-cards/);
  let frame = await previewFrame(page);
  expect(await sectionsIn(page)).toContain("home/s03-cards-copy1");
  await expect(frame.locator("#features")).toHaveCount(1);
  await expect(frame.locator("#features-s03-cards-copy1")).toHaveCount(1);
  await expect(frame.locator("article.card")).toHaveCount(6);

  // Remove the copy again.
  await change(page, () => item(page, "home/s03-cards-copy1").getByRole("button", { name: "Remove home/s03-cards-copy1" }).click(), /Removed/);
  expect(await sectionsIn(page)).not.toContain("home/s03-cards-copy1");
  await expect(page.getByTestId("removed-item")).toHaveCount(1);

  // Insert a section from the other page at the end of the main region.
  await page.getByLabel("Section (from any page)").selectOption("menu|menu/s03-testimonials");
  await page.getByLabel("Region").selectOption({ label: "r2 · inside main" });
  await change(page, () => page.getByRole("button", { name: "Insert section" }).click(), /Inserted a copy of menu\/s03-testimonials/);
  expect((await sectionsIn(page)).at(-2)).toBe("home/menu-s03-testimonials-copy1");
  await expect((await previewFrame(page)).getByText("Best bread in town.")).toBeVisible();

  // Split the hero at its button: the hero stays as the wrapper around two parts.
  await item(page, "home/s02-hero").getByRole("button", { name: "Split home/s02-hero" }).click();
  await page.getByLabel("Split at elements matching").fill("a.button");
  await change(page, () => page.getByRole("button", { name: "Split section" }).click(), /split into 2 parts/);
  expect((await sectionsIn(page)).slice(1, 4)).toEqual(["home/s02-hero", "home/s02-hero-p1", "home/s02-hero-p2"]);
  // The cards repeat from a list: splitting them is refused with the reason.
  await item(page, "home/s03-cards").getByRole("button", { name: "Split home/s03-cards" }).click();
  await page.getByLabel("Split at elements matching").fill("article.card");
  await page.getByRole("button", { name: "Split section" }).click();
  await expect(page.getByRole("alert").filter({ hasText: "repeated from a list" })).toBeVisible();

  // Exclude by selector.
  await page.getByRole("textbox", { name: "Selector", exact: true }).fill(".promo");
  await change(page, () => page.getByRole("button", { name: "Exclude", exact: true }).click(), /Excluded 0 section\(s\) and 1 element/);
  frame = await previewFrame(page);
  await expect(frame.getByText("Limited offer this week")).toHaveCount(0);
  await expect(frame.getByText("Fresh bread daily")).toBeVisible();

  // The split parts' text is edited like any section's.
  const before = await buildOf(page);
  await page.getByLabel("s02-hero-p1 · heading").fill("Warm loaves, split and edited");
  await page.getByRole("button", { name: "Save page" }).click();
  await rebuilt(page, before);
  await expect((await previewFrame(page)).locator("h1")).toHaveText("Warm loaves, split and edited");

  // Mobile viewport still renders every section.
  await page.getByRole("button", { name: "Mobile" }).click();
  expect((await sectionsIn(page)).length).toBeGreaterThanOrEqual(8);
  await page.getByRole("button", { name: "Desktop" }).click();
  expect(consoleErrors).toEqual([]);
});

test("a declaration detached from its token keeps the captured colour when the brand colour changes", async ({ page }) => {
  test.setTimeout(120_000);
  await page.goto(templatePage);
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 30_000 });
  await page.getByText(/^Declarations \(/).click();
  const h1 = page.locator('[data-testid="token-binding"]', { hasText: "h1 { color }" });
  await expect(h1).toHaveAttribute("data-state", "bound");
  await expect(h1).toContainText("#b45309"); // the captured declaration
  await change(page, () => h1.getByRole("button", { name: "Detach" }).click(), /Detached/);
  await expect(page.locator('[data-testid="token-binding"]', { hasText: "h1 { color }" })).toHaveAttribute("data-state", "detached");

  const before = await buildOf(page);
  const colourLabel = (await page.locator('label[for^="color-"]').first().textContent())!;
  await page.getByLabel(colourLabel, { exact: true }).fill("#ff0066");
  await page.getByRole("button", { name: "Save brand" }).click();
  await rebuilt(page, before);
  const frame = await previewFrame(page);
  await expect.poll(() => frame.evaluate(() => getComputedStyle(document.querySelector(".button")!).backgroundColor).catch(() => "")).toBe("rgb(255, 0, 102)");
  expect(await frame.evaluate(() => getComputedStyle(document.querySelector("h1")!).color)).toBe("rgb(180, 83, 9)");
});

test("missing assets are shown with the preview", async ({ page, request }) => {
  await page.goto(templatePage);
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 30_000 });
  const url = (await page.getByRole("link", { name: "Open preview in new tab" }).getAttribute("href"))!;
  expect((await request.get(`${url}assets/site/img/not-there.png`)).status()).toBe(404);
  await expect(page.getByTestId("missing-assets")).toContainText("/assets/site/img/not-there.png", { timeout: 10_000 });
});

test("Web's checks pass on the edited template; undoing an override keeps edits; the edited template downloads", async ({ page, request }) => {
  test.setTimeout(180_000);
  await page.goto(templatePage);
  await page.getByRole("button", { name: "Run checks" }).click();
  await expect(page.getByTestId("structure-message")).toHaveText(/Checks done: 2 of 2 page\(s\) passed/, { timeout: 60_000 });
  await expect(page.getByTestId("verification")).toContainText("home: sections in composition order, 0 missing asset(s), 0 broken link(s), 0 duplicate id(s)");

  // Undo the first override (the move): replayed from the generated template, edits kept.
  await expect(page.getByTestId("override").first()).toHaveAttribute("data-op", "move");
  await page.getByTestId("override").first().getByRole("button", { name: "Undo" }).click();
  await expect(page.getByTestId("structure-message")).toHaveText(/Replayed from the generated template; \d+ edited value\(s\) kept\./, { timeout: 60_000 });
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 60_000 });
  // The preview restarts on the replayed copy: the cards are back before the form.
  await expect
    .poll(async () => {
      const order = await sectionsIn(page).catch(() => [] as (string | null)[]);
      return order.indexOf("home/s02-hero") < order.indexOf("home/s03-cards") && order.indexOf("home/s03-cards") < order.indexOf("home/s04-form");
    }, { timeout: 30_000 })
    .toBe(true);
  await expect((await previewFrame(page)).locator("h1")).toHaveText("Warm loaves, split and edited");
  await expect(page.getByTestId("override")).toHaveCount(6); // the refused split was never recorded
  await expect(page.locator('[data-testid="override"][data-status="failed"]')).toHaveCount(0);

  const href = (await page.getByRole("link", { name: "Download edited template" }).getAttribute("href"))!;
  const res = await request.get(href);
  expect(res.status()).toBe(200);
  const files = unzipSync(new Uint8Array(await res.body()));
  for (const n of ["template/compose.mjs", "template/composition/home.json", "template/overrides.json", "template/tokens/token-map.json", "template/build.mjs", "raw-capture/pages/home/document.original.html", "section-inventory.json", "reports/coverage.json", "reports/verification.json", "reports/source-edits.json", "EDITING.md"]) {
    expect(Object.keys(files), n).toContain(`website-template/${n}`);
  }
  const layout = new TextDecoder().decode(files["website-template/template/layouts/home.html"]);
  expect(layout).toContain("{{@section home/menu-s03-testimonials-copy1}}");
  await page.getByRole("button", { name: "Stop" }).click();
});
